import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Check for clinical/cohort variables with strong association
    clinical_p_values = []
    clinical_effects = []

    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical' or feats.types[i] == 'cohort':
            # For clinical/cohort variables, check correlation with outcome
            corr = np.corrcoef(feats.x[:, i], feats.y)[0, 1]
            if not np.isnan(corr):
                p_val = 2 * (1 - stats.norm.cdf(abs(corr) * np.sqrt(len(feats.y) - 2) / np.sqrt(1 - corr**2)))
            else:
                p_val = 1.0
            clinical_p_values.append(p_val)
            clinical_effects.append(np.mean(feats.x[feats.y == 1, i]) - np.mean(feats.x[feats.y == 0, i]))
        else:
            clinical_p_values.append(1.0)
            clinical_effects.append(0.0)

    # Find clinical features with p < 0.05
    clinical_indices = [i for i, p in enumerate(clinical_p_values) if p < 0.05]

    if clinical_indices:
        # Use the most significant clinical feature as driver
        best_clinical_idx = clinical_indices[np.argmin([clinical_p_values[i] for i in clinical_indices])]
        driver_fid = feats.ids[best_clinical_idx]

        # Select features not highly correlated with the driver
        driver_idx = feats.column(driver_fid)
        selected_features = []

        for fid in feats.ids:
            if fid == driver_fid:
                continue
            feat_idx = feats.column(fid)
            if feat_idx >= 0:  # Ensure valid column index
                corr = np.corrcoef(feats.x[:, driver_idx], feats.x[:, feat_idx])[0, 1]
                if not np.isnan(corr) and abs(corr) < 0.6:
                    selected_features.append(fid)

        return Design(
            drivers=(driver_fid,),
            columns=tuple(selected_features[:10]),  # Limit to 10 features
            products=(),
            loadings={}
        )

    # No clinical driver found; find top individual associations
    p_values = []
    effects = []

    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical' or feats.types[i] == 'cohort':
            corr = np.corrcoef(feats.x[:, i], feats.y)[0, 1]
            if not np.isnan(corr):
                p_val = 2 * (1 - stats.norm.cdf(abs(corr) * np.sqrt(len(feats.y) - 2) / np.sqrt(1 - corr**2)))
            else:
                p_val = 1.0
        else:
            y0 = feats.x[feats.y == 0, i]
            y1 = feats.x[feats.y == 1, i]
            if len(y0) > 1 and len(y1) > 1:
                t_stat, p_val = stats.ttest_ind(y0, y1, equal_var=False)
            else:
                p_val = 1.0
        p_values.append(p_val)
        effects.append(np.mean(feats.x[feats.y == 1, i]) - np.mean(feats.x[feats.y == 0, i]))

    # Get indices of significant features (p < 0.05)
    significant_indices = [i for i, p in enumerate(p_values) if p < 0.05]

    if not significant_indices:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Sort by effect size
    significant_indices.sort(key=lambda i: abs(effects[i]), reverse=True)

    # Take top features
    top_indices = significant_indices[:MAX_DRIVERS]
    drivers = tuple(feats.ids[i] for i in top_indices)
    columns = tuple(feats.ids[i] for i in significant_indices[:10])  # Limit columns

    # Look for interactions among top drivers
    products = []
    for i in range(min(len(drivers), 3)):
        for j in range(i+1, min(len(drivers), 3)):
            products.append((drivers[i], drivers[j]))

    # Simple weighted loading based on effect sizes
    loadings = {}
    for i in top_indices:
        loadings[feats.ids[i]] = effects[i]

    return Design(drivers=drivers, columns=columns, products=tuple(products), loadings=loadings)

